import type { RequestHandler } from 'express';

import {
  hashApiKey,
  type ApiConsumerRepository,
  type ActiveConsumer,
} from './api-consumer.repository';

interface Window {
  startedAt: number;
  count: number;
}

function unauthorized(response: Parameters<RequestHandler>[1]): void {
  response.setHeader('WWW-Authenticate', 'ApiKey');
  response.status(401).json({
    error: { code: 'API_KEY_UNAUTHORIZED', message: 'A valid active API key is required.' },
  });
}

function secondsToUtcMidnight(now = new Date()): number {
  const midnight = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1);
  return Math.max(1, Math.ceil((midnight - now.getTime()) / 1000));
}

export function createConsumerAuthentication(repository: ApiConsumerRepository): RequestHandler {
  const windows = new Map<string, Window>();
  return (request, response, next) => {
    const rawKey = request.get('X-API-Key');
    if (!rawKey || !/^sat_live_[A-Za-z0-9_-]{43}$/.test(rawKey)) {
      unauthorized(response);
      return;
    }
    void repository
      .findActiveConsumer(hashApiKey(rawKey))
      .then(async (consumer) => {
        if (!consumer) {
          unauthorized(response);
          return;
        }
        if (!withinRateLimit(consumer, windows, response)) return;
        const quota = await repository.consumeDailyQuota(consumer.consumerId, consumer.dailyQuota);
        response.setHeader('X-Quota-Limit', consumer.dailyQuota);
        response.setHeader('X-Quota-Remaining', Math.max(0, consumer.dailyQuota - quota.used));
        response.setHeader('X-Quota-Reset', secondsToUtcMidnight());
        if (!quota.allowed) {
          response.status(429).json({
            error: {
              code: 'QUOTA_EXCEEDED',
              message: 'The daily consumer quota has been reached.',
            },
          });
          return;
        }
        response.locals.apiConsumer = consumer;
        next();
      })
      .catch(next);
  };
}

function withinRateLimit(
  consumer: ActiveConsumer,
  windows: Map<string, Window>,
  response: Parameters<RequestHandler>[1],
): boolean {
  const now = Date.now();
  const existing = windows.get(consumer.consumerId);
  const window =
    !existing || now - existing.startedAt >= 60_000 ? { startedAt: now, count: 0 } : existing;
  window.count += 1;
  windows.set(consumer.consumerId, window);
  const reset = Math.max(1, Math.ceil((window.startedAt + 60_000 - now) / 1000));
  response.setHeader('RateLimit-Limit', consumer.rateLimitPerMinute);
  response.setHeader(
    'RateLimit-Remaining',
    Math.max(0, consumer.rateLimitPerMinute - window.count),
  );
  response.setHeader('RateLimit-Reset', reset);
  if (window.count <= consumer.rateLimitPerMinute) return true;
  response.setHeader('Retry-After', reset);
  response.status(429).json({
    error: {
      code: 'RATE_LIMIT_EXCEEDED',
      message: 'Too many requests. Retry after the current rate-limit window.',
    },
  });
  return false;
}

import type { ApiConsumer, ApiConsumerIssue } from '@sport-analytics/contracts';
import { createHash } from 'node:crypto';
import type { Pool } from 'pg';

import { executeQuery, getDatabasePool, withTransaction, type QueryExecutor } from '../../database';

interface ConsumerRow {
  id: string;
  name: string;
  rateLimitPerMinute: number;
  dailyQuota: number;
  createdAt: Date;
}

interface KeyRow {
  id: string;
  consumerId: string;
  prefix: string;
  createdAt: Date;
  revokedAt: Date | null;
}

export interface ActiveConsumer {
  consumerId: string;
  rateLimitPerMinute: number;
  dailyQuota: number;
}

export interface ApiConsumerRepository {
  issue(ownerAccountId: string, issue: ApiConsumerIssue, key: GeneratedKey): Promise<ApiConsumer>;
  list(ownerAccountId: string): Promise<ApiConsumer[]>;
  rotate(ownerAccountId: string, consumerId: string, key: GeneratedKey): Promise<ApiConsumer>;
  revoke(ownerAccountId: string, consumerId: string, keyId: string): Promise<void>;
  findActiveConsumer(keyHash: string): Promise<ActiveConsumer | null>;
  consumeDailyQuota(consumerId: string, quota: number): Promise<{ allowed: boolean; used: number }>;
}

interface GeneratedKey {
  raw: string;
  prefix: string;
  hash: string;
}

export function hashApiKey(rawKey: string): string {
  return createHash('sha256').update(rawKey).digest('hex');
}

function mapConsumer(row: ConsumerRow, keys: KeyRow[]): ApiConsumer {
  return {
    id: row.id,
    name: row.name,
    rateLimitPerMinute: row.rateLimitPerMinute,
    dailyQuota: row.dailyQuota,
    createdAt: row.createdAt.toISOString(),
    keys: keys.map((key) => ({
      id: key.id,
      prefix: key.prefix,
      createdAt: key.createdAt.toISOString(),
      revokedAt: key.revokedAt?.toISOString() ?? null,
    })),
  };
}

async function readConsumer(
  executor: QueryExecutor,
  consumerId: string,
): Promise<ApiConsumer | null> {
  const consumers = await executeQuery<ConsumerRow>(
    executor,
    `SELECT api_consumer_id::text AS id, name,
      rate_limit_per_minute AS "rateLimitPerMinute", daily_quota AS "dailyQuota", created_at AS "createdAt"
     FROM api_consumer WHERE api_consumer_id = $1`,
    [consumerId],
  );
  const consumer = consumers.rows[0];
  if (!consumer) return null;
  const keys = await executeQuery<KeyRow>(
    executor,
    `SELECT api_consumer_key_id::text AS id, api_consumer_id::text AS "consumerId",
      key_prefix AS prefix, created_at AS "createdAt", revoked_at AS "revokedAt"
     FROM api_consumer_key WHERE api_consumer_id = $1 ORDER BY api_consumer_key_id`,
    [consumerId],
  );
  return mapConsumer(consumer, keys.rows);
}

export function createApiConsumerRepository(pool: Pool = getDatabasePool()): ApiConsumerRepository {
  return {
    async issue(ownerAccountId, issue, key) {
      return withTransaction(pool, async (client) => {
        const inserted = await executeQuery<ConsumerRow>(
          client,
          `INSERT INTO api_consumer (owner_app_user_id, name, rate_limit_per_minute, daily_quota)
           VALUES ($1, $2, $3, $4)
           RETURNING api_consumer_id::text AS id, name, rate_limit_per_minute AS "rateLimitPerMinute",
             daily_quota AS "dailyQuota", created_at AS "createdAt"`,
          [ownerAccountId, issue.name, issue.rateLimitPerMinute, issue.dailyQuota],
        );
        const consumer = inserted.rows[0]!;
        await executeQuery(
          client,
          `INSERT INTO api_consumer_key (api_consumer_id, key_prefix, key_hash) VALUES ($1, $2, $3)`,
          [consumer.id, key.prefix, key.hash],
        );
        return (await readConsumer(client, consumer.id))!;
      });
    },
    async list(ownerAccountId) {
      const rows = await executeQuery<{ id: string }>(
        pool,
        `SELECT api_consumer_id::text AS id FROM api_consumer
         WHERE owner_app_user_id = $1 ORDER BY api_consumer_id`,
        [ownerAccountId],
      );
      return Promise.all(
        rows.rows.map((row) => readConsumer(pool, row.id).then((consumer) => consumer!)),
      );
    },
    async rotate(ownerAccountId, consumerId, key) {
      return withTransaction(pool, async (client) => {
        const owned = await executeQuery<{ id: string }>(
          client,
          `SELECT api_consumer_id::text AS id FROM api_consumer
           WHERE api_consumer_id = $1 AND owner_app_user_id = $2 FOR UPDATE`,
          [consumerId, ownerAccountId],
        );
        if (!owned.rows[0]) throw new ApiConsumerNotFoundError();
        await executeQuery(
          client,
          `UPDATE api_consumer_key SET revoked_at = now()
          WHERE api_consumer_id = $1 AND revoked_at IS NULL`,
          [consumerId],
        );
        await executeQuery(
          client,
          `INSERT INTO api_consumer_key (api_consumer_id, key_prefix, key_hash)
          VALUES ($1, $2, $3)`,
          [consumerId, key.prefix, key.hash],
        );
        return (await readConsumer(client, consumerId))!;
      });
    },
    async revoke(ownerAccountId, consumerId, keyId) {
      const result = await executeQuery(
        pool,
        `UPDATE api_consumer_key SET revoked_at = now()
         WHERE api_consumer_key_id = $1 AND revoked_at IS NULL
           AND api_consumer_id = $2 AND EXISTS (
             SELECT 1 FROM api_consumer WHERE api_consumer_id = $2 AND owner_app_user_id = $3
           )`,
        [keyId, consumerId, ownerAccountId],
      );
      if (result.rowCount !== 1) throw new ApiConsumerNotFoundError();
    },
    async findActiveConsumer(keyHash) {
      const result = await executeQuery<ActiveConsumer>(
        pool,
        `SELECT consumer.api_consumer_id::text AS "consumerId",
          consumer.rate_limit_per_minute AS "rateLimitPerMinute", consumer.daily_quota AS "dailyQuota"
         FROM api_consumer_key key
         JOIN api_consumer consumer ON consumer.api_consumer_id = key.api_consumer_id
         WHERE key.key_hash = $1 AND key.revoked_at IS NULL`,
        [keyHash],
      );
      return result.rows[0] ?? null;
    },
    async consumeDailyQuota(consumerId, quota) {
      const result = await executeQuery<{ requestCount: number }>(
        pool,
        `INSERT INTO api_consumer_daily_usage (api_consumer_id, usage_date, request_count)
         VALUES ($1, CURRENT_DATE, 1)
         ON CONFLICT (api_consumer_id, usage_date) DO UPDATE
           SET request_count = api_consumer_daily_usage.request_count + 1
           WHERE api_consumer_daily_usage.request_count < $2
         RETURNING request_count AS "requestCount"`,
        [consumerId, quota],
      );
      const used = result.rows[0]?.requestCount;
      return used === undefined ? { allowed: false, used: quota } : { allowed: true, used };
    },
  };
}

/** Avoid opening the application pool for routes that do not use consumer keys. */
export function createLazyApiConsumerRepository(): ApiConsumerRepository {
  let repository: ApiConsumerRepository | undefined;
  const resolved = () => (repository ??= createApiConsumerRepository());
  return {
    issue: (...args) => resolved().issue(...args),
    list: (...args) => resolved().list(...args),
    rotate: (...args) => resolved().rotate(...args),
    revoke: (...args) => resolved().revoke(...args),
    findActiveConsumer: (...args) => resolved().findActiveConsumer(...args),
    consumeDailyQuota: (...args) => resolved().consumeDailyQuota(...args),
  };
}

export class ApiConsumerNotFoundError extends Error {
  constructor() {
    super('The API consumer or key was not found.');
  }
}

import request from 'supertest';
import { describe, expect, test, vi } from 'vitest';

import type { ApiConsumerRepository } from '../../src/modules/api-consumers/api-consumer.repository';
import type { ApiConsumerService } from '../../src/modules/api-consumers/api-consumer.service';
import { createTestAccount, createTestApp } from '../test-app';

const consumer = {
  id: '7',
  name: 'Partner dashboard',
  rateLimitPerMinute: 2,
  dailyQuota: 3,
  createdAt: '2026-09-07T10:00:00.000Z',
  keys: [
    { id: '9', prefix: 'sat_live_example', createdAt: '2026-09-07T10:00:00.000Z', revokedAt: null },
  ],
};

function service(): ApiConsumerService {
  return {
    issue: vi.fn().mockResolvedValue({
      ...consumer,
      apiKey: 'sat_live_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',
    }),
    list: vi.fn().mockResolvedValue([consumer]),
    rotate: vi.fn().mockResolvedValue({
      ...consumer,
      apiKey: 'sat_live_bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb',
    }),
    revoke: vi.fn().mockResolvedValue(undefined),
  };
}

function repository(overrides: Partial<ApiConsumerRepository> = {}): ApiConsumerRepository {
  return {
    issue: vi.fn(),
    list: vi.fn(),
    rotate: vi.fn(),
    revoke: vi.fn(),
    findActiveConsumer: vi
      .fn()
      .mockResolvedValue({ consumerId: '7', rateLimitPerMinute: 2, dailyQuota: 3 }),
    consumeDailyQuota: vi.fn().mockResolvedValue({ allowed: true, used: 1 }),
    ...overrides,
  };
}

describe('API consumer key lifecycle and protections', () => {
  test('only administrators can issue a key and the secret is returned once', async () => {
    const apiConsumerService = service();
    const response = await request(
      createTestApp(
        undefined,
        undefined,
        async () => createTestAccount({ role: 'admin' }),
        undefined,
        undefined,
        undefined,
        undefined,
        undefined,
        undefined,
        undefined,
        undefined,
        undefined,
        apiConsumerService,
        repository(),
      ),
    )
      .post('/api/v1/admin/api-consumers')
      .set('Authorization', 'Bearer admin-token')
      .send({ name: 'Partner dashboard', rateLimitPerMinute: 2, dailyQuota: 3 })
      .expect(201);
    expect(response.body.data.apiKey).toMatch(/^sat_live_/);
    expect(apiConsumerService.issue).toHaveBeenCalledOnce();

    const listed = await request(
      createTestApp(
        undefined,
        undefined,
        async () => createTestAccount({ role: 'admin' }),
        undefined,
        undefined,
        undefined,
        undefined,
        undefined,
        undefined,
        undefined,
        undefined,
        undefined,
        apiConsumerService,
        repository(),
      ),
    )
      .get('/api/v1/admin/api-consumers')
      .set('Authorization', 'Bearer admin-token')
      .expect(200);
    expect(JSON.stringify(listed.body)).not.toContain(
      'sat_live_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',
    );
  });

  test('rejects missing, malformed and revoked keys without exposing key details', async () => {
    const revoked = repository({ findActiveConsumer: vi.fn().mockResolvedValue(null) });
    const app = createTestApp(
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      revoked,
    );
    await request(app)
      .get('/api/v1/consumer/competitions')
      .expect('WWW-Authenticate', 'ApiKey')
      .expect(401);
    const response = await request(app)
      .get('/api/v1/consumer/competitions')
      .set('X-API-Key', 'sat_live_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa')
      .expect(401);
    expect(response.body.error.code).toBe('API_KEY_UNAUTHORIZED');
  });

  test('enforces a consumer rate limit and emits rate and quota metadata', async () => {
    const repo = repository();
    const app = createTestApp(
      undefined,
      {
        async listCompetitions() {
          return { data: [], pagination: { nextCursor: null } };
        },
      } as never,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      repo,
    );
    const key = 'sat_live_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';
    await request(app)
      .get('/api/v1/consumer/competitions')
      .set('X-API-Key', key)
      .expect('RateLimit-Limit', '2')
      .expect('X-Quota-Remaining', '2')
      .expect(200);
    await request(app).get('/api/v1/consumer/competitions').set('X-API-Key', key).expect(200);
    const limited = await request(app)
      .get('/api/v1/consumer/competitions')
      .set('X-API-Key', key)
      .expect(429);
    expect(limited.body.error.code).toBe('RATE_LIMIT_EXCEEDED');
  });

  test('returns quota exceeded when the durable counter refuses another request', async () => {
    const repo = repository({
      consumeDailyQuota: vi.fn().mockResolvedValue({ allowed: false, used: 3 }),
    });
    const app = createTestApp(
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      repo,
    );
    const response = await request(app)
      .get('/api/v1/consumer/competitions')
      .set('X-API-Key', 'sat_live_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa')
      .expect(429);
    expect(response.headers['x-quota-limit']).toBe('3');
    expect(response.body.error.code).toBe('QUOTA_EXCEEDED');
  });

  test.each([
    '/api/v1/consumer/fixtures/1/events',
    '/api/v1/consumer/fixtures/1/events/export.json',
    '/api/v1/consumer/fixtures/1/statistics',
    '/api/v1/consumer/fixtures/1/statistics/runs/events/export.json',
  ])('does not allow consumer reads to bypass key enforcement through %s', async (path) => {
    const response = await request(createTestApp()).get(path).expect(401);

    expect(response.headers['www-authenticate']).toBe('ApiKey');
    expect(response.body.error.code).toBe('API_KEY_UNAUTHORIZED');
  });

  test('shares the rate limit between consumer aliases and protected fixture event reads', async () => {
    const app = createTestApp(
      undefined,
      {
        async listCompetitions() {
          return { data: [], pagination: { nextCursor: null } };
        },
        async listFixtures() {
          return { data: [], pagination: { nextCursor: null } };
        },
      } as never,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      repository({
        findActiveConsumer: vi
          .fn()
          .mockResolvedValue({ consumerId: '7', rateLimitPerMinute: 1, dailyQuota: 3 }),
      }),
    );
    const key = 'sat_live_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';

    await request(app).get('/api/v1/consumer/competitions').set('X-API-Key', key).expect(200);
    const limited = await request(app)
      .get('/api/v1/consumer/fixtures/1/events')
      .set('X-API-Key', key)
      .expect(429);

    expect(limited.body.error.code).toBe('RATE_LIMIT_EXCEEDED');
  });
});

import { Pool } from 'pg';
import { afterAll, beforeAll, describe, expect, test } from 'vitest';

import { executeQuery } from '../../src/database';
import {
  createApiConsumerRepository,
  hashApiKey,
} from '../../src/modules/api-consumers/api-consumer.repository';
import { assertSafeTestDatabase } from '../../scripts/test-database-safety';

const sourcePrefix = `api-consumer-test-${process.pid}`;

describe.sequential('API consumer key persistence', () => {
  let pool: Pool;
  let accountId: string;

  beforeAll(async () => {
    const url = assertSafeTestDatabase(
      process.env.DATABASE_URL_TEST,
      process.env.DATABASE_URL,
      process.env.NODE_ENV,
    );
    pool = new Pool({ connectionString: url.toString() });
    const account = await executeQuery<{ id: string }>(
      pool,
      `INSERT INTO app_user (auth_provider, auth_subject, display_name, application_role, submitter_approval_state)
      VALUES ('test', $1, 'API Consumer Test', 'admin', 'not_requested') RETURNING app_user_id::text AS id`,
      [sourcePrefix],
    );
    accountId = account.rows[0]!.id;
  });

  afterAll(async () => {
    await pool.end();
  });

  test('stores only hashes, rotates/revokes active key lookup, and atomically enforces the daily quota', async () => {
    const repository = createApiConsumerRepository(pool);
    const first = 'sat_live_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';
    const issued = await repository.issue(
      accountId,
      { name: 'Database consumer', rateLimitPerMinute: 2, dailyQuota: 2 },
      {
        raw: first,
        prefix: first.slice(0, 17),
        hash: hashApiKey(first),
      },
    );
    const persisted = await executeQuery<{ hash: string; rawCount: number }>(
      pool,
      `SELECT key_hash AS hash,
      (SELECT count(*)::int FROM api_consumer_key WHERE key_hash = $2) AS "rawCount" FROM api_consumer_key WHERE api_consumer_id = $1`,
      [issued.id, first],
    );
    expect(persisted.rows[0]!.hash).toBe(hashApiKey(first));
    expect(persisted.rows[0]!.rawCount).toBe(0);
    expect(await repository.findActiveConsumer(hashApiKey(first))).toMatchObject({
      consumerId: issued.id,
    });

    const second = 'sat_live_bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb';
    const rotated = await repository.rotate(accountId, issued.id, {
      raw: second,
      prefix: second.slice(0, 17),
      hash: hashApiKey(second),
    });
    expect(rotated.keys.filter((key) => key.revokedAt === null)).toHaveLength(1);
    expect(await repository.findActiveConsumer(hashApiKey(first))).toBeNull();
    expect(await repository.findActiveConsumer(hashApiKey(second))).toMatchObject({
      consumerId: issued.id,
    });

    await expect(repository.consumeDailyQuota(issued.id, 2)).resolves.toEqual({
      allowed: true,
      used: 1,
    });
    await expect(repository.consumeDailyQuota(issued.id, 2)).resolves.toEqual({
      allowed: true,
      used: 2,
    });
    await expect(repository.consumeDailyQuota(issued.id, 2)).resolves.toEqual({
      allowed: false,
      used: 2,
    });
  });
});

